#!/bin/sh
# Adapt the vendored CaDiCaL tree to R's C API.
#
# Run from the package root by tools/vendor-cadical.sh, after the upstream
# copy and before checksums are recorded.
#
# R CMD check rejects compiled code that can terminate the process or that
# writes to stdout/stderr instead of R's console, so every such call site is
# rerouted:
#
#   printf/fprintf/fputs/fputc/vfprintf -> Rprintf / REprintf / REvprintf
#   abort(), exit()                     -> Rf_error, via ZUSAT_FATAL
#   the fork/exec pipe paths in file.cpp -> compiled out (ZUSAT_NO_PIPES)
#
# These are expressed as substitutions rather than as context diffs on
# purpose: a .patch breaks on any upstream edit near a hunk, while a
# substitution either still matches or visibly stops matching. The final
# guard below fails the build if a pattern stops matching anything.
set -eu

DEST="src/cadical"
[ -d "$DEST" ] || { echo "patch-for-r: no $DEST" >&2; exit 1; }

# ---------------------------------------------------------------- header
# Declared by hand rather than by including <R.h>: R's headers define
# macros (length, error, ...) that collide with CaDiCaL's own names across
# 90 translation units. A plain declaration needs no header at all, so it
# is safe as the first line of any file, C or C++.
cat > "$DEST/zusat_r_compat.h" <<'HEADER'
/* Generated by tools/vendor/patch-for-r.sh -- do not edit by hand. */
#ifndef ZUSAT_R_COMPAT_H
#define ZUSAT_R_COMPAT_H

/* R_NO_REMAP keeps R from defining `error`, `length` and friends as macros,
   which would collide with CaDiCaL's own names across 90 files. These two
   headers are the narrow ones: they declare Rprintf/REprintf/Rvprintf/
   REvprintf and Rf_error and little else. R's real declarations are used
   rather than hand-written prototypes so the calling convention -- and
   dllimport on Windows -- always matches whatever R we build against. */
#ifndef R_NO_REMAP
#define R_NO_REMAP
#endif

#include <R_ext/Print.h>
#include <R_ext/Error.h>

/* CaDiCaL calls abort()/exit() on internal errors and invalid API use.
   Both would take R's process down with them, so they raise an R condition
   instead. This unwinds through C++ frames without running destructors --
   acceptable only because it is already a non-recoverable path. */
#define ZUSAT_FATAL(what) \
  Rf_error ("CaDiCaL %s (%s:%d)", what, __FILE__, __LINE__)

#endif /* ZUSAT_R_COMPAT_H */
HEADER

# ----------------------------------------------------------- rewrite calls
# Headers are rewritten too, not just .cpp/.c: contract.hpp and cover.hpp
# define macros whose bodies call fprintf(stderr)/abort(), and those expand
# inside whichever object includes them -- which is how the symbols reach
# collect.o and solver.o without appearing in any .cpp.
#
# Spacing is matched with \s* rather than a literal space, and exit with any
# status rather than 1, because upstream is free to write printf( or exit (2)
# at any release. Both the rewrite and the end-state guard below used to
# require exactly one space, so that form would have passed both and reached
# R CMD check as a WARNING -- drift the guard exists to catch and could not
# structurally see.
#
# perl runs in slurp mode (-0777) because several calls are split across
# lines. The [^;]*? guard keeps a match inside one statement so a non-greedy
# wildcard cannot run past the call it belongs to. Trailing backslashes in
# macro bodies survive: \s* stops at a backslash, so the continuation stays.
rewrite_one () {
  perl -0777 -pi -e '
    s/\bvfprintf\s*\(stderr,\s*/REvprintf (/g;
    s/\bvfprintf\s*\(stdout,\s*/Rvprintf (/g;
    s/\bfprintf\s*\(stderr,\s*/REprintf (/g;
    s/\bfprintf\s*\(stdout,\s*/Rprintf (/g;
    s/\bfputs\s*\(([^;]*?),\s*stdout\)/Rprintf ("%s", $1)/gs;
    s/\bfputs\s*\(([^;]*?),\s*stderr\)/REprintf ("%s", $1)/gs;
    s/\bfputc\s*\(([^;]*?),\s*stdout\)/Rprintf ("%c", $1)/gs;
    s/\bfputc\s*\(([^;]*?),\s*stderr\)/REprintf ("%c", $1)/gs;
    s/\bfflush\s*\(stdout\)/((void) 0)/g;
    s/\bfflush\s*\(stderr\)/((void) 0)/g;
    s/(?<![_[:alnum:]])printf\s*\(/Rprintf (/g;
    s/(?<![_[:alnum:]])abort\s*\(\)/ZUSAT_FATAL ("aborted")/g;
    s/(?<![_[:alnum:]])exit\s*\(\d+\)/ZUSAT_FATAL ("fatal error")/g;
  ' "$1"
}

for f in "$DEST"/*.cpp "$DEST"/*.c "$DEST"/*.hpp "$DEST"/*.h; do
  case "$f" in *zusat_r_compat.h) continue;; esac
  rewrite_one "$f"
  # Only files that ended up calling into R need the declarations.
  if grep -qE '(Rprintf|REprintf|Rvprintf|REvprintf|ZUSAT_FATAL)' "$f" \
     && ! grep -q 'zusat_r_compat.h' "$f"; then
    printf '#include "zusat_r_compat.h"\n%s' "$(cat "$f")" > "$f.tmp"
    mv "$f.tmp" "$f"
  fi
done

# ------------------------------------- solver.cpp: no std-stream comparison
# Solver::build picks a Terminal by comparing its FILE* against stdout and
# stderr, which references both globals. Both Terminals are now NULL-backed
# and permanently disconnected, so the choice has no effect: drop it.
perl -0777 -pi -e '
  s/  assert \(file == stdout \|\| file == stderr\);\n\n  Terminal \*terminal;\n\n  if \(file == stdout\)\n    terminal = &tout;\n  else if \(file == stderr\)\n    terminal = &terr;\n  else\n    terminal = 0;\n/  (void) file;\n\n  Terminal *terminal = 0;\n/s;
' "$DEST/solver.cpp"

# --------------------------------------------------- file.cpp: no fork/exec
# The compressed-file paths fork and exec gzip/xz, then _exit() in the child.
# zusat never opens a file through CaDiCaL -- clauses arrive through the API
# -- so this compiles the whole path out. Upstream already builds this way on
# Windows, which is what makes it a tested configuration rather than a new one.
perl -pi -e 's/^#ifndef _WIN32$/#if !defined(_WIN32) \&\& !defined(ZUSAT_NO_PIPES)/' \
  "$DEST/file.cpp"

# ------------------------------------------ terminal.cpp: no stdout/stderr
# Terminal only ever writes when 'connected', which is isatty() on the stream
# it was handed. Passing NULL keeps the globals out of the object file; every
# writer already early-returns, so the pointer is never dereferenced.
perl -pi -e '
  s/^Terminal tout \(stdout\);$/Terminal tout (NULL);/;
  s/^Terminal terr \(stderr\);$/Terminal terr (NULL);/;
  s/^  assert \(file\);$/  if (!file) { use_colors = connected = false; return; }/;
  s/^  int fd = fileno \(f\);$/  int fd = fileno (f);/;
' "$DEST/terminal.cpp"

# ------------------------------------------------------------------ guard
# A substitution that stops matching is how this script fails quietly, so
# assert the end state instead of trusting the rewrite.
fail=0
check_absent () {
  hits=$(grep -nE "$1" "$DEST"/*.cpp "$DEST"/*.c "$DEST"/*.hpp "$DEST"/*.h \
           2>/dev/null | grep -v zusat_r_compat || true)
  if [ -n "$hits" ]; then
    echo "patch-for-r: $2 still present:" >&2
    echo "$hits" | head -5 >&2
    fail=1
  fi
}
check_absent '(^|[^_[:alnum:]])printf[[:space:]]*\(' 'bare printf'
check_absent '(^|[^_[:alnum:]])abort[[:space:]]*\(\)' 'abort()'
check_absent '(^|[^_[:alnum:]])exit[[:space:]]*\([0-9]+\)' 'exit()'
check_absent '(fputs|fputc|fprintf)[[:space:]]*\([^;]*(stdout|stderr)' 'stdio write to stdout/stderr'
check_absent 'Terminal (tout|terr) \((stdout|stderr)\)' 'Terminal on a std stream'
check_absent '(fflush|vfprintf)[[:space:]]*\((stdout|stderr)' 'fflush/vfprintf on a std stream'
check_absent '[=!]= *(stdout|stderr)' 'comparison against a std stream'
[ "$fail" -eq 0 ] || { echo "patch-for-r: rewrite incomplete" >&2; exit 1; }

echo "patch-for-r: rerouted CaDiCaL output and fatal paths to R"
